declare(strict_types=1);ob_start();require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/super_app_v700.php';$id=(int)($_GET['id']??0);$r=v700_one('tourism_restaurants_v700',$id,"status='active'");if(!$r){http_response_code(404);exit('Restaurant not found.');}$u=v700_user();$flash='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){if(!$u){header('Location: '.v700_login_url($_SERVER['REQUEST_URI']??'/restaurant.php?id='.$id));exit;}csrf_check();$_POST['restaurant_id']=$id;$bid=v700_create_restaurant_booking((int)$u['id'],$_POST);$flash='Table booking request submitted. ID #'.$bid;}}catch(Throwable $e){$err=$e->getMessage();}v700_track('tourism','view','restaurant',$id);v700_public_header($r['name'],strip_tags((string)($r['description']?:'Restaurant booking on ShahkotPK')),'tourism');?>
<main><section class="v700-account-hero"><div class="v700-shell"><span class="v700-kicker">🍽 RESTAURANT <?=$r['verified']?'· VERIFIED':''?></span><h1><?=e($r['name'])?></h1><p><?=e($r['cuisine']?:'Local dining')?> · <?=e($r['area']?:$r['address']?:'Shahkot')?></p></div></section><section class="v700-section soft"><div class="v700-shell"><div class="v700-grid" style="grid-template-columns:1.3fr .7fr"><section class="v700-panel"><h2>About</h2><p><?=nl2br(e($r['description']?:'Restaurant details will be updated by the venue.'))?></p><h3>Opening Hours</h3><p><?=e($r['opening_hours']?:'Contact restaurant for current hours.')?></p><?php if($r['phone']):?><p><b>Phone:</b> <?=e($r['phone'])?></p><?php endif;?></section><aside class="v700-panel"><?php if($flash):?><div class="v700-alert success"><?=e($flash)?></div><?php endif;?><?php if($err):?><div class="v700-alert error"><?=e($err)?></div><?php endif;?><h2>Reserve a table</h2><form method="post" class="v700-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><div class="two"><label>Date<input type="date" name="booking_date" required></label><label>Time<input type="time" name="booking_time" required></label></div><label>Guests<input type="number" min="1" name="guests" value="2"></label><div class="two"><label>Name<input name="customer_name" required value="<?=e($u['name']??'')?>"></label><label>Phone<input name="customer_phone" required value="<?=e($u['phone']??'')?>"></label></div><label>Special request<textarea name="special_request"></textarea></label><button class="v700-btn primary">Request Reservation</button></form></aside></div></div></section></main><?php v700_public_footer(); ?>
